export interface ParsedVCardContact {
  name?: string;
  email?: string;
  phone?: string;
  organization?: string;
  title?: string;
  note?: string;
  address?: string;
  raw: string;
}

/**
 * Parses raw QR code string, which can be:
 * 1. Standard vCard 2.1 / 3.0 / 4.0 format generated by attendee badge / Apple Wallet
 * 2. Plain email address or phone number
 * 3. JSON encoded contact card object
 */
export function parseVCardString(raw: string): ParsedVCardContact {
  const trimmed = raw.trim();
  const result: ParsedVCardContact = { raw: trimmed };

  if (!trimmed) {
    return result;
  }

  // Case 1: JSON payload
  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
    try {
      const obj = JSON.parse(trimmed);
      if (typeof obj === 'object' && obj !== null) {
        if (typeof obj.name === 'string') result.name = obj.name;
        if (typeof obj.email === 'string') result.email = obj.email;
        if (typeof obj.phone === 'string') result.phone = obj.phone;
        if (typeof obj.organization === 'string') result.organization = obj.organization;
        return result;
      }
    } catch {
      // not json, continue
    }
  }

  // Case 2: Standard vCard format
  if (trimmed.toUpperCase().includes('BEGIN:VCARD')) {
    const lines = trimmed.split(/\r\n|\r|\n/);
    for (const rawLine of lines) {
      const line = rawLine.trim();
      const upper = line.toUpperCase();

      if (upper.startsWith('FN:') || upper.startsWith('FN;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.name = line.slice(colonIdx + 1).trim();
      } else if (upper.startsWith('EMAIL:') || upper.startsWith('EMAIL;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.email = line.slice(colonIdx + 1).trim().toLowerCase();
      } else if (upper.startsWith('TEL:') || upper.startsWith('TEL;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.phone = line.slice(colonIdx + 1).trim();
      } else if (upper.startsWith('ORG:') || upper.startsWith('ORG;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.organization = line.slice(colonIdx + 1).trim();
      } else if (upper.startsWith('TITLE:') || upper.startsWith('TITLE;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.title = line.slice(colonIdx + 1).trim();
      } else if (upper.startsWith('NOTE:') || upper.startsWith('NOTE;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.note = line.slice(colonIdx + 1).trim();
      } else if (upper.startsWith('ADR:') || upper.startsWith('ADR;')) {
        const colonIdx = line.indexOf(':');
        if (colonIdx !== -1) result.address = line.slice(colonIdx + 1).replace(/;/g, ' ').trim();
      }
    }
    return result;
  }

  // Case 3: Plain email
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
    result.email = trimmed.toLowerCase();
    return result;
  }

  // Case 4: Plain phone
  if (/^\+?[0-9\s\-()]{7,}$/.test(trimmed)) {
    result.phone = trimmed;
    return result;
  }

  // Default fallback: name or text
  result.name = trimmed;
  return result;
}
